local vars hours attendance
foreach v of local vars {
 generate double c_`v' = `v'
}

foreach v of varlist hours-attendance {
 generate double d_`v' = `v'*2
}

forvalues i = 1/3 {
 generate double p`i' = hours^`i'
 local last `i'
}
generate double last = `last'

forvalues i = 2 4 to 8 {
 generate double v`i' = `i'
}

forvalues i = 3/1 {
 generate double skipped = 1
}
generate double retained = hours

local n = 2
forvalues i = 1/`n' {
 forvalues j = 1/2 {
  if `i' == `j' {
   generate double c`i'`j' = `i' + `j'
  }
  else {
   generate double c`i'`j' = 0
  }
 }
}

if hours == 1 {
 generate double reached = 1
}
if . {
 generate double missing_true = 1
}

foreach value in "first group" "last group" {
 local last "`value'"
}
generate chosen = "`last'"

forvalues i = 1/3 {
 generate double repeated = `i'
}
generate double later = 1

local i 99
forvalues i=1/2 {
}
generate after_for = "`i'"
local j before
foreach j in a b {
}
generate after_each = "`j'"
forvalues i=1/1 {
 forvalues i=2/2 {
 }
 generate nested = "`i'"
}

local n 0
foreach v of varlist hours hours {
 local n = `n' + 1
}
generate double count = `n'
